typeSurface.body:
import { Balances, ChainApi, util } from '@defillama/sdk';
import sdk from '@defillama/sdk';
export type Chain = string

const { blocks: { getChainBlocks } } = util

export type ChainBlocks = Awaited<ReturnType<typeof getChainBlocks>>

export type ChainEndpoints = {
  [chain: string]: string
}

export type FetchResultBase = {
  timestamp?: number;
};

export type FetchResultV2 = {
  [key: string]: FetchResponseValue | undefined;
};

export type FetchResultGeneric = FetchResultBase & {
  [key: string]: FetchResponseValue | undefined;
}

export type FetchOptions = {
  createBalances: () => Balances;
  getBlock: (timestamp: number, chain: string, chainBlocks: ChainBlocks) => Promise<number>;
  getLogs: (params: FetchGetLogsOptions) => Promise<any[]>;
  streamLogs: (params: Parameters<typeof sdk.indexer.getLogs>[0] & {
    targetsFilter?: string[] | Set<string>
  }) => Promise<any[]>;
  toTimestamp: number;
  fromTimestamp: number;
  startOfDay: number;
  getFromBlock: () => Promise<number>;
  getToBlock: () => Promise<number>;
  chain: string,
  api: ChainApi,
  fromApi: ChainApi,
  toApi: ChainApi,
  startTimestamp: number,
  endTimestamp: number,
  getStartBlock: () => Promise<number>,
  getEndBlock: () => Promise<number>,
  dateString: string,
  preFetchedResults?: any,
  moduleUID: string,  // randomly generated unique identifier for the module, useful for caching (used only for batch processing dune queries for now)
  startOfDayId?: string, // id used in some subgraphs to identify daily data, usually it's the startOfDay timestamp divided by 86400
  metadata?: {
    [key: string]: any
    adapterType?: string
    protocolName?: string
    name?: string
    id?: string
    runType?: string
    isHourlyAdapter?: boolean
  }
}

export type FetchGetLogsOptions = {
  maxBlockRange?: number,
  eventAbi?: string,
  topic?: string,
  target?: string,
  targets?: string[],
  onlyArgs?: boolean,
  fromBlock?: number,
  toBlock?: number,
  flatten?: boolean,
  cacheInCloud?: boolean,
  entireLog?: boolean,
  skipCacheRead?: boolean,
  skipCache?: boolean,
  skipIndexer?: boolean,
  topics?: string[],
  noTarget?: boolean,
  parseLog?: boolean,
}

export type FetchV2 = (
  options: FetchOptions,
) => Promise<FetchResultV2>;


export type BaseAdapterChainConfig = {
  start?: string; // date can be in "YYYY-MM-DD" format -  indicates when the adapter can start fetching data
  deadFrom?: string; // date can be in "YYYY-MM-DD" format - indicates when the adapter should stop fetching data
  fetch?: FetchV2;
  runAtCurrTime?: boolean;
}

export const whitelistedBaseAdapterKeys = new Set([
  'start', 'deadFrom', 'fetch', 'runAtCurrTime'
])

export type BaseAdapter = {
  [chain: string]: BaseAdapterChainConfig
};

export enum ProtocolType {
  CHAIN = 'chain',
  PROTOCOL = 'protocol',
  COLLECTION = 'collection',
}

export enum Dependencies {
  DUNE = 'dune',
  ALLIUM = 'allium'
}


export type AdapterBase = {
  timetravel?: boolean
  isExpensiveAdapter?: boolean,
  dependencies?: Dependencies[]
  protocolType?: ProtocolType;
  version?: number;
  deadFrom?: string;
  allowNegativeValue?: boolean;
  doublecounted?: boolean;
  methodology?: string | IJSON<string>;
  breakdownMethodology?: Record<string, string | IJSON<string>>;
  fetch?: FetchV2;
  chains?: (string | [string, BaseAdapterChainConfig])[]
  prefetch?: FetchV2;
  runAtCurrTime?: boolean;
  start?: string; // date can be in "YYYY-MM-DD" format
  _randomUID?: string; // sometimes fee & volume adapters share the same code, we can optimize the run by caching the results - We stopped caching these results but left as is as it is used in batching dune queries, we can re-use it later if needed
  pullHourly?: boolean;
  skipBreakdownValidation?: boolean; // this is to skip the validation that requires at least one of dailyRevenue, dailySupplySideRevenue or dailyProtocolRevenue to be present when dailyFees is present, this is useful for some adapters that have a breakdown in their dailyFees but dont have a clear way to attribute the fees to either supply side or protocol revenue
}

export type SimpleAdapter = AdapterBase & {
  adapter?: BaseAdapter
}

export type Adapter = SimpleAdapter;
export type FetchResponseValue = string | number | Balances;

/**
 * Include here new adaptors types
 */

// VOLUME
export type FetchResultVolume = FetchResultBase & {
  dailyVolume?: FetchResponseValue
  shortOpenInterestAtEnd?: FetchResponseValue
  longOpenInterestAtEnd?: FetchResponseValue
  openInterestAtEnd?: FetchResponseValue
  dailyBridgeVolume?: FetchResponseValue
  dailyNormalizedVolume?: FetchResponseValue
  dailyActiveLiquidity?: FetchResponseValue
};

// FEES
export type FetchResultFees = FetchResultBase & {
  dailyFees?: FetchResponseValue;
  dailyUserFees?: FetchResponseValue;
  dailyRevenue?: FetchResponseValue;
  dailyProtocolRevenue?: FetchResponseValue;
  dailyHoldersRevenue?: FetchResponseValue;
  dailySupplySideRevenue?: FetchResponseValue;
  dailyBribesRevenue?: FetchResponseValue;
  dailyTokenTaxes?: FetchResponseValue;
  dailyOtherIncome?: FetchResponseValue;
  dailyOperatingIncome?: FetchResponseValue;
  dailyNetIncome?: FetchResponseValue;
};

// INCENTIVES
export type FetchResultIncentives = FetchResultBase & {
  tokenIncentives?: FetchResponseValue
};

// AGGREGATORS
export type FetchResultAggregators = FetchResultBase & {
  dailyVolume?: FetchResponseValue
};

export type FetchResultActiveUsers = FetchResultBase & {
  dailyActiveUsers?: FetchResponseValue;
  dailyTransactionsCount?: FetchResponseValue;
  dailyGasUsed?: FetchResponseValue;
};

export type FetchResultNewUsers = FetchResultBase & {
  dailyNewUsers?: FetchResponseValue;
};

// OPTIONS
export type FetchResultOptions = FetchResultBase & {
  dailyPremiumVolume?: FetchResponseValue
  dailyNotionalVolume?: FetchResponseValue
  shortOpenInterestAtEnd?: FetchResponseValue
  longOpenInterestAtEnd?: FetchResponseValue
  openInterestAtEnd?: FetchResponseValue
};

// LIQUIDATIONS
export type FetchResultLiquidations = FetchResultBase & {
  dailyCollateralLiquidated?: FetchResponseValue
  dailyLiquidationVolume?: FetchResponseValue
};

export enum AdapterType {
  FEES = 'fees',
  DEXS = 'dexs',
  INCENTIVES = 'incentives',
  AGGREGATORS = 'aggregators',
  DERIVATIVES = 'derivatives',
  OPTIONS = 'options',
  PROTOCOLS = 'protocols',
  OPEN_INTEREST = 'open-interest',
  // ROYALTIES = 'royalties',
  AGGREGATOR_DERIVATIVES = 'aggregator-derivatives',
  BRIDGE_AGGREGATORS = 'bridge-aggregators',
  NORMALIZED_VOLUME = 'normalized-volume',
  NFT_VOLUME = 'nft-volume',
  ACTIVE_USERS = 'active-users',
  NEW_USERS = 'new-users',
  LIQUIDATIONS = 'liquidations',
}

export type FetchResult = FetchResultVolume & FetchResultFees & FetchResultAggregators & FetchResultOptions & FetchResultIncentives & FetchResultActiveUsers & FetchResultNewUsers & FetchResultLiquidations

export const whitelistedDimensionKeys = new Set([
  'startTimestamp', 'chain', 'timestamp', 'block',

  'dailyVolume', 'shortOpenInterestAtEnd', 'longOpenInterestAtEnd', 'openInterestAtEnd', 'dailyBridgeVolume', 'dailyNormalizedVolume', 'dailyActiveLiquidity',
  'totalFees', 'dailyFees', 'dailyUserFees', 'dailyRevenue', 'dailyProtocolRevenue', 'dailyHoldersRevenue', 'dailySupplySideRevenue', 'dailyBribesRevenue', 'dailyTokenTaxes',
  'tokenIncentives',
  'dailyOtherIncome', 'dailyOperatingIncome', 'dailyNetIncome',, 'dailyPremiumVolume', 'dailyNotionalVolume',
  'dailyActiveUsers', 'dailyNewUsers', 'dailyTransactionsCount', 'dailyGasUsed',
  'dailyCollateralLiquidated', 'dailyLiquidationVolume',
])
export const accumulativeKeySet = new Set([
  'totalVolume', 'totalBridgeVolume', 'tokenIncentives', 'totalPremiumVolume', 'totalNotionalVolume',
  'totalFees', 'totalRevenue', 'totalProtocolRevenue', 'totalSupplySideRevenue', 'totalUserFees', 'totalHoldersRevenue', 'totalOtherIncome', 'totalOperatingIncome', 'totalNetIncome'
])

// End of specific adaptors type

export interface IJSON<T> {
  [key: string]: T
}

export const ADAPTER_TYPES = Object.values(AdapterType).filter((adapterType: any) => adapterType !== AdapterType.PROTOCOLS)

closure.body:
import { FetchOptions, FetchResultV2, SimpleAdapter } from "../../adapters/types";
import { CHAIN } from "../../helpers/chains";

const FWA = "0xB276F62DB0ce8CA2Ca5bc522695bE604521eAc1c";
// Splitter: receives all protocol fees via payoutFees(), splits them between the
// team (ownerShareBps) and the v1 snapshot soulbound-NFT holders (the remainder)
const SPLITTER = "0x1C175b9F0e8C73eD3e677e1cBb1B5A2DD4373Bfe";
const BUYBACK = "0xabc98D86eA62919399c4211251890308Ce37A6BF";
const BPS = 10_000n;

const METRICS = {
  AcquisitionFees: 'Acquisition Fees',
  SettlementFees: 'Settlement Fees',
  RetainedSettlements: 'Retained Settlement Penalties',
  TopListingReward: 'Top Listing Reward',
  AcquisitionToNFTHolders: 'Acquisition Fees to Snapshot NFT Holders',
  SettlementToNFTHolders: 'Settlement Fees to Snapshot NFT Holders',
  RetainedToNFTHolders: 'Retained Settlement Penalties to Snapshot NFT Holders',
  TokenBuyBack: 'Token Buy Back',
  RetroactiveBuybacks: 'Retroactive buybacks',
  FeesToTeam: 'Fees To Team',
};

const ABIS = {
  OwnerFeesAccrued: "event OwnerFeesAccrued(uint256 amount)",
  EarningsAccrued: "event EarningsAccrued(address indexed depositor, uint256 indexed listingId, uint256 amount)",
  TopListingFunded: "event TopListingFunded(uint256 indexed listingId, uint256 amount, uint256 newPot)",
  NFTKept: "event NFTKept(uint256 indexed listingId, address indexed purchaser, address indexed depositor, uint256 backing)",
  NFTRelisted: "event NFTRelisted(uint256 indexed listingId, uint256 indexed newListingId, uint256 toDepositor)",
  DepositorBidAccepted: "event DepositorBidAccepted(uint256 indexed listingId, address indexed purchaser, address indexed depositor, uint256 payout, uint256 retained)",
  DepositorBidAcceptedAsTokens: "event DepositorBidAcceptedAsTokens(uint256 indexed listingId, address indexed purchaser, address indexed depositor, uint256 ethPayout, uint256 retained, uint256 tokenOut)",
  ProtocolFeesToToken: "event ProtocolFeesToToken(uint256 amount)",
  AcquisitionRequested: "event AcquisitionRequested(uint256 indexed requestId, address indexed purchaser, uint256 acquisitionFee, uint256 totalWeight)",
  NFTAllocated: "event NFTAllocated(uint256 indexed requestId, uint256 indexed listingId, address indexed purchaser, address depositor, uint256 value, uint256 randomWord)",
  Bought: "event Bought(address indexed caller, address indexed recipient, uint256 indexed buybackNumber, uint256 ethSpent, uint256 amountBought, uint256 callerReward)",
};

const fetch = async (options: FetchOptions): Promise<FetchResultV2> => {
  const dailyVolume = options.createBalances();
  const dailyFees = options.createBalances();
  const dailyRevenue = options.createBalances();
  const dailySupplySideRevenue = options.createBalances();
  const dailyHoldersRevenue = options.createBalances();

  const [ownerSettlementFeeBps, retainedToProtocol, ownerShareBps] = await Promise.all([
    options.api.call({ target: FWA, abi: 'uint256:ownerSettlementFeeBps' }),
    options.api.call({ target: FWA, abi: 'bool:retainedToProtocol' }),
    options.api.call({ target: SPLITTER, abi: 'uint16:ownerShareBps' }),
  ]);

  const [ownerFees, earnings, topListingFunded, nftKept, nftRelisted, bidAccepted, bidAcceptedAsTokens, feesToToken, allocated, bought] = await Promise.all([
    options.getLogs({ target: FWA, eventAbi: ABIS.OwnerFeesAccrued }),
    options.getLogs({ target: FWA, eventAbi: ABIS.EarningsAccrued }),
    options.getLogs({ target: FWA, eventAbi: ABIS.TopListingFunded }),
    options.getLogs({ target: FWA, eventAbi: ABIS.NFTKept }),
    options.getLogs({ target: FWA, eventAbi: ABIS.NFTRelisted }),
    options.getLogs({ target: FWA, eventAbi: ABIS.DepositorBidAccepted }),
    options.getLogs({ target: FWA, eventAbi: ABIS.DepositorBidAcceptedAsTokens }),
    options.getLogs({ target: FWA, eventAbi: ABIS.ProtocolFeesToToken }),
    options.getLogs({ target: FWA, eventAbi: ABIS.NFTAllocated }),
    options.getLogs({ target: BUYBACK, eventAbi: ABIS.Bought }),
  ]);

  // Pull volume: the escrowed acquisition price of each pull, counted when the VRF settlement
  // allocates the NFT. NFTAllocated doesn't carry the price, so look it up on the matching 
  // AcquisitionRequested, fetched with a ~1-day block lookback since a request can settle in a later window.
  const requested = await options.getLogs({
    target: FWA,
    eventAbi: ABIS.AcquisitionRequested,
    fromBlock: Number(await options.getFromBlock()) - 7_200,
  });
  const feeByRequest = new Map<string, bigint>();
  requested.forEach((log: any) => feeByRequest.set(String(log.requestId), BigInt(log.acquisitionFee)));
  let pullVolume = 0n;
  allocated.forEach((log: any) => { pullVolume += feeByRequest.get(String(log.requestId)) ?? 0n; });
  dailyVolume.addGasToken(pullVolume);

  // Quick-sell payouts: ETH returned to purchasers who accept the depositor's standing bid
  // (85% of the listing backing) instead of keeping the NFT — the TCG-buyback analog.
  // Netted out of both fees and supply-side revenue (depositor backings fund the payouts)
  // under the acquisition label, keeping Fees = Revenue + SupplySideRevenue exact.
  let quickSellPayouts = 0n;
  bidAccepted.forEach((log: any) => { quickSellPayouts += BigInt(log.payout); });
  bidAcceptedAsTokens.forEach((log: any) => { quickSellPayouts += BigInt(log.ethPayout); });
  dailyFees.addGasToken(-quickSellPayouts, METRICS.AcquisitionFees);
  dailySupplySideRevenue.addGasToken(-quickSellPayouts, METRICS.AcquisitionFees);

  // Acquisition fees distributed to depositors: equal split across active listings + top-listing pot
  earnings.forEach((log: any) => {
    dailyFees.addGasToken(log.amount, METRICS.AcquisitionFees);
    dailySupplySideRevenue.addGasToken(log.amount, METRICS.AcquisitionFees);
  });
  topListingFunded.forEach((log: any) => {
    dailyFees.addGasToken(log.amount, METRICS.AcquisitionFees);
    dailySupplySideRevenue.addGasToken(log.amount, METRICS.TopListingReward);
  });

  // Settlement fee on NFT outcomes: events carry the depositor payout net of the cut,
  // so gross the fee back up: fee = net * bps / (BPS - bps)
  const settleBps = BigInt(ownerSettlementFeeBps);
  let settlementFees = 0n;
  nftKept.forEach((log: any) => { settlementFees += BigInt(log.backing) * settleBps / (BPS - settleBps); });
  nftRelisted.forEach((log: any) => { settlementFees += BigInt(log.toDepositor) * settleBps / (BPS - settleBps); });
  dailyFees.addGasToken(settlementFees, METRICS.SettlementFees);

  // Retained penalty on ETH/token settlements (backing minus the purchaser's 85% payout).
  // Routed to the protocol when retainedToProtocol, otherwise shared among active depositors.
  let retained = 0n;
  bidAccepted.forEach((log: any) => { retained += BigInt(log.retained); });
  bidAcceptedAsTokens.forEach((log: any) => { retained += BigInt(log.retained); });
  dailyFees.addGasToken(retained, METRICS.RetainedSettlements);
  if (!retainedToProtocol) dailySupplySideRevenue.addGasToken(retained, METRICS.RetainedSettlements);

  // Protocol cut of acquisition fees: OwnerFeesAccrued aggregates all protocol accruals,
  // so the acquisition cut is the residual after the settlement-side accruals above
  let totalOwnerFees = 0n;
  ownerFees.forEach((log: any) => { totalOwnerFees += BigInt(log.amount); });
  let acquisitionCut = totalOwnerFees - settlementFees - (retainedToProtocol ? retained : 0n);
  if (acquisitionCut < 0n) acquisitionCut = 0n;
  dailyFees.addGasToken(acquisitionCut, METRICS.AcquisitionFees);

  // Attribution of the protocol's take: a protocolFeeToTokenBps slice can be
  // diverted to FWA-token buybacks at payout time (holders revenue); the rest goes to the
  // Splitter, which pays the team ownerShareBps (70%) and the v1 snapshot soulbound-NFT
  // holders the remainder (30%)
  const protocolTake = settlementFees + (retainedToProtocol ? retained : 0n) + acquisitionCut;
  let toTokenBuyback = 0n;
  feesToToken.forEach((log: any) => { toTokenBuyback += BigInt(log.amount); });
  let splitterShare = protocolTake - toTokenBuyback;
  if (splitterShare < 0n) splitterShare = 0n;
  const teamShare = splitterShare * BigInt(ownerShareBps) / BPS;
  const nftHoldersShare = splitterShare - teamShare;
  const proRata = (amount: bigint, share: bigint) => protocolTake > 0n ? amount * share / protocolTake : 0n;
  const components: [bigint, string, string][] = [
    [acquisitionCut, METRICS.AcquisitionFees, METRICS.AcquisitionToNFTHolders],
    [settlementFees, METRICS.SettlementFees, METRICS.SettlementToNFTHolders],
    [retainedToProtocol ? retained : 0n, METRICS.RetainedSettlements, METRICS.RetainedToNFTHolders],
  ];
  components.forEach(([amount, label, nftLabel]) => {
    dailyRevenue.addGasToken(proRata(amount, teamShare), label);
    dailySupplySideRevenue.addGasToken(proRata(amount, nftHoldersShare), nftLabel);
  });
  // ProtocolFeesToToken fires when the slice is paid out, which can be a later window than the
  // one that accrued it, so it can exceed this window's protocolTake - that is why splitterShare
  // clamps above. Book only the part this window actually earned as revenue, or revenue plus
  // supply side would exceed the fees the window recorded. Holders revenue keeps the full amount:
  // it is an attribution of the buyback and is allowed to land in a different window.
  const buybackFromWindowFees = toTokenBuyback > protocolTake ? protocolTake : toTokenBuyback;
  dailyRevenue.addGasToken(buybackFromWindowFees, METRICS.TokenBuyBack);
  dailyHoldersRevenue.addGasToken(toTokenBuyback, METRICS.TokenBuyBack);

  // Retroactive buybacks: 327 ETH of already-earned team fees swapped for FWA on a fixed
  // 2-hour schedule via the FWABuyback executor. Holders revenue only because the funding fees
  // were already booked as protocol revenue when they accrued
  bought.forEach((log: any) => { dailyHoldersRevenue.addGasToken(log.ethSpent, METRICS.RetroactiveBuybacks); });

  // Revenue = ProtocolRevenue + HoldersRevenue: both buyback legs are deducted from the team's share
  const dailyProtocolRevenue = dailyRevenue.clone(1, METRICS.FeesToTeam);
  dailyProtocolRevenue.subtract(dailyHoldersRevenue, METRICS.FeesToTeam);

  return { dailyVolume, dailyFees, dailyRevenue, dailyProtocolRevenue, dailyHoldersRevenue, dailySupplySideRevenue };
};

const methodology = {
  Volume: "Gross ETH paid by purchasers for acquisitions (pulls), net of refunded, expired, or slippage-cancelled requests.",
  Fees: "Net Acquisition fees paid by NFT purchasers, plus settlement fees taken from listing backings.",
  Revenue: "Team share of the protocol's cut of acquisition and settlement fees, plus any fees diverted to FWA-token buybacks.",
  ProtocolRevenue: "Team share of the protocol's fee cut, per the Splitter contract's live split, minus the FWA-token buybacks counted under HoldersRevenue.",
  HoldersRevenue: "FWA-token buybacks funded from protocol fees, plus retroactive scheduled buybacks funded from previously earned team fees.",
  SupplySideRevenue: "Share of net acquisition fees distributed to NFT depositors (equal split across active listings plus the top-listing pot), plus the snapshot soulbound-NFT holders' share of protocol fees via the Splitter.",
};

const breakdownMethodology = {
  Fees: {
    [METRICS.AcquisitionFees]: "The total ETH paid by purchasers to acquire a random NFT from the pool, net of refunded requests and of quick-sell payouts returned to purchasers (85% of the listing backing when they accept the depositor's standing bid).",
    [METRICS.SettlementFees]: "1% of the listing backing, charged when a settlement returns the backing to the depositor (purchaser keeps or relists the NFT).",
    [METRICS.RetainedSettlements]: "15% of the listing backing retained when a purchaser accepts the depositor's standing bid instead of keeping the NFT.",
  },
  Revenue: {
    [METRICS.AcquisitionFees]: "Protocol cut (1%) of acquisition fees.",
    [METRICS.SettlementFees]: "Settlement fees accrue entirely to the protocol.",
    [METRICS.RetainedSettlements]: "Retained settlement penalties accrue to the protocol.",
    [METRICS.TokenBuyBack]: "Protocol fees diverted to FWA-token buybacks.",
  },
  SupplySideRevenue: {
    [METRICS.AcquisitionFees]: "Share of net acquisition fees distributed to NFT depositors, split equally across active listings.",
    [METRICS.TopListingReward]: "Share of acquisition fees accruing to the depositor of the top-backed listing.",
    [METRICS.AcquisitionToNFTHolders]: "Snapshot soulbound-NFT holders' share (via the Splitter) of the protocol's cut of acquisition fees.",
    [METRICS.SettlementToNFTHolders]: "Snapshot soulbound-NFT holders' share (via the Splitter) of settlement fees.",
    [METRICS.RetainedToNFTHolders]: "Snapshot soulbound-NFT holders' share (via the Splitter) of retained settlement penalties.",
    [METRICS.RetainedSettlements]: "Settlement discount redistributed among active NFT depositors.",
  },
  ProtocolRevenue: {
    [METRICS.FeesToTeam]: "Team share of acquisition fees, settlement fees and retained settlement penalties, minus fee-funded and retroactive FWA-token buybacks.",
  },
  HoldersRevenue: {
    [METRICS.TokenBuyBack]: "Protocol fees diverted to FWA-token buybacks.",
    [METRICS.RetroactiveBuybacks]: "Scheduled FWA-token buybacks (327 ETH in 1 ETH slices every 2 hours) funded from previously earned team fees.",
  },
};

const adapter: SimpleAdapter = {
  version: 2,
  pullHourly: true,
  allowNegativeValue: true, // quick-sell payouts and refunds can exceed same-window pull spend; buybacks can exceed the window's team share of fees
  fetch,
  chains: [CHAIN.ETHEREUM],
  start: '2026-07-20',
  methodology,
  breakdownMethodology,
};

export default adapter;

import * as sdk from "@defillama/sdk";
import { Adapter } from "../adapters/types";
import { CHAIN } from "../helpers/chains";
import { METRIC } from "../helpers/metrics";
import { request, gql } from "graphql-request";
import type { FetchOptions } from "../adapters/types"
import { getTimestampAtStartOfDayUTC } from "../utils/date";
import { addTokensReceived } from "../helpers/token";
import coreAssets from "../helpers/coreAssets.json"

const endpoints: Record<string, string> = {
  [CHAIN.ETHEREUM]: sdk.graph.modifyEndpoint('F7qb71hWab6SuRL5sf6LQLTpNahmqMsBnnweYHzLGUyG'),
}

const PROTOCOL_FEE_RATIO = 0.1 // 10%
const LIDO_V2_LAUNCH = '2023-05-15' // StakingRouter (per-module fee split) went live; earlier windows read 0
const LIDO_MEV_REWARDS_VAULT = '0x388c818ca8b9251b393131c08a736a67ccb19297';
const LIDO_STAKING_ROUTER = '0xFdDf38947aFB03C621C71b06C9C70bce73f12999';
const STAKING_ROUTER_FEE_DISTRIBUTION_ABI = 'function getStakingFeeAggregateDistributionE4Precision() view returns (uint16 modulesFee, uint16 treasuryFee)';
const LIDO_AGENT = '0x3e40D73EB977Dc6a537aF587D48316feE66E9C8c'
const BUYBACKS_SAFE = '0xf6F0732c1e9971497342C295141566E6F1A31e96'

const fetch = async (options: FetchOptions) => {
  const dateId = Math.floor(getTimestampAtStartOfDayUTC(options.toTimestamp) / 86400)

  const graphQuery = gql
    `{
    financialsDailySnapshot(id: ${dateId}) {
        dailyTotalRevenueUSD
        dailyProtocolSideRevenueUSD
        cumulativeTotalRevenueUSD
        cumulativeProtocolSideRevenueUSD
        dailySupplySideRevenueUSD
        cumulativeSupplySideRevenueUSD
    }
  }`;

  const graphRes = await request(endpoints[options.chain], graphQuery);

  const dailyTotalRevenueUSD = Number(graphRes.financialsDailySnapshot.dailyTotalRevenueUSD)
  const dailyProtocolRevenueUSD = dailyTotalRevenueUSD * PROTOCOL_FEE_RATIO
  const dailySupplySideRevenueUSD = dailyTotalRevenueUSD - dailyProtocolRevenueUSD

  // Lido's 10% protocol take is split between node operators and the DAO treasury, weighted
  // across staking modules by their active-validator share.
  let operatorShare: number
  let treasuryShare: number
  if (options.dateString < LIDO_V2_LAUNCH) {
    // Before Lido V2 the StakingRouter didn't exist, so calling it reverts. The 10% fee was a
    // fixed 5%/5% split for the whole V1 era (the 2022-07-15 insurance->treasury redirect,
    // research.lido.fi/t/.../2528, left the operator share unchanged at 5%), so a flat 50/50
    // operator/treasury split is accurate. Booking the operator share as Revenue (the old
    // treasuryShare=1 fallback) overstated protocol Revenue ~2x for this era.
    operatorShare = 0.5
    treasuryShare = 0.5
  } else {
    // Read the live aggregate split off the StakingRouter at the window's end block so historical
    // accuracy follows the on-chain rate (e.g. module 1 changed from 5%/5% to 3.5%/6.5% on
    // 2025-12-24, tx 0x470e74a0…).
    const feeSplit = await options.toApi.call({
      target: LIDO_STAKING_ROUTER,
      abi: STAKING_ROUTER_FEE_DISTRIBUTION_ABI,
    })
    const modulesFeeBp = Number(feeSplit.modulesFee)
    const treasuryFeeBp = Number(feeSplit.treasuryFee)
    const totalFeeBp = modulesFeeBp + treasuryFeeBp
    // Post-V2 the StakingRouter always returns a configured non-zero split, so a 0 here is a
    // transient read fault, not a real allocation. Fail loudly rather than silently guessing a
    // ratio, which would mis-split protocol Revenue vs the node-operator supply-side share.
    if (totalFeeBp === 0) throw new Error(`Lido: StakingRouter returned a zero fee split for ${options.dateString}; refusing to guess the treasury/operator ratio`)
    operatorShare = modulesFeeBp / totalFeeBp
    treasuryShare = treasuryFeeBp / totalFeeBp
  }

  // MEV and execution rewards
  const mevFeesETH = options.createBalances()
  const transactions = await sdk.indexer.getTransactions({
    chain: options.chain,
    transactionType: 'to',
    addresses: [LIDO_MEV_REWARDS_VAULT],
    from_block: Number(options.fromApi.block),
    to_block: Number(options.toApi.block),
  })
  if (transactions) {
    for (const tx of transactions) {
      mevFeesETH.addGasToken(tx.value)
    }
  }

  const totalMevFees = await mevFeesETH.getUSDValue()
  const protocolMevFees = totalMevFees * PROTOCOL_FEE_RATIO
  const supplySideMevFees = totalMevFees - protocolMevFees

  const stakingProtocolFees = dailyProtocolRevenueUSD - protocolMevFees
  const stakingSupplySide = dailySupplySideRevenueUSD - supplySideMevFees

  const dailyFees = options.createBalances()
  const dailyRevenue = options.createBalances()
  const dailySupplySideRevenue = options.createBalances()
  const dailyHoldersRevenue = options.createBalances()

  dailyFees.addUSDValue(dailyTotalRevenueUSD - totalMevFees, METRIC.STAKING_REWARDS)
  dailyFees.addUSDValue(totalMevFees, METRIC.MEV_REWARDS)

  dailySupplySideRevenue.addUSDValue(stakingSupplySide, 'Staking rewards to ETH stakers')
  dailySupplySideRevenue.addUSDValue(supplySideMevFees, 'MEV rewards to ETH stakers')

  // Split the protocol take into the DAO-treasury share (kept by the Lido DAO) and the
  // module-operator share (paid to node operators). Totals are preserved; only the breakdown
  // gains granularity. Operator and treasury shares are summed across staking + MEV sources.
  dailyRevenue.addUSDValue(stakingProtocolFees * treasuryShare, METRIC.STAKING_REWARDS)
  dailyRevenue.addUSDValue(protocolMevFees * treasuryShare, METRIC.MEV_REWARDS)

  dailySupplySideRevenue.addUSDValue(stakingProtocolFees * operatorShare, 'Staking rewards to node operators')
  dailySupplySideRevenue.addUSDValue(protocolMevFees * operatorShare, 'MEV rewards to node operators')

  const buybacks = await addTokensReceived({
    options,
    target: LIDO_AGENT,
    fromAdddesses: [BUYBACKS_SAFE],
    tokens: [coreAssets.ethereum.LIDO] 
  })
  dailyHoldersRevenue.addBalances(buybacks, "LDO Accumulation Program")

  // Buybacks are paid out of the DAO-treasury share
  const dailyProtocolRevenue = options.createBalances()
  dailyProtocolRevenue.addBalances(dailyRevenue, 'DAO treasury share')
  dailyProtocolRevenue.subtract(dailyHoldersRevenue, 'DAO treasury share')

  return {
    dailyFees,
    dailyUserFees: 0,
    dailyRevenue,
    dailyProtocolRevenue,
    dailySupplySideRevenue,
    dailyHoldersRevenue
  };
};

const adapter: Adapter = {
  fetch,
  chains: [CHAIN.ETHEREUM],
  start: '2020-12-19',
  allowNegativeValue: true, // protocol revenue nets out LDO buybacks, which land in lumps of 1.7M-6.5M LDO (~$1.5M on 2026-06-01 vs ~$75k/day treasury revenue)
  methodology: {
    Fees: "Staking rewards earned by all staked ETH",
    UserFees: "Lido takes no fees from users.",
    Revenue: "Lido takes a 10% fee on staking rewards; Revenue is only the DAO-treasury portion of that fee (net of the node-operator share, which is a cost of production booked as SupplySideRevenue). From Lido V2 (2023-05-15) the treasury/operator split is the validator-share-weighted aggregate read live from the StakingRouter; before V2 the split was a fixed 5%/5%, so half the fee is treasury.",
    HoldersRevenue: "Tracks LIDO bought back by the DAO as part of the LDO Accumulation Program",
    ProtocolRevenue: "DAO-treasury portion of the 10% fee, minus the LDO bought back under the LDO Accumulation Program; excludes the node-operator share.",
    SupplySideRevenue: "Staking rewards earned by stETH holders plus the node-operator share of the 10% fee (paid to operators for running validators)."
  },
  breakdownMethodology: {
    Fees: {
      [METRIC.STAKING_REWARDS]: 'ETH rewards from running Beacon chain validators.',
      [METRIC.MEV_REWARDS]: 'ETH rewards from MEV tips on ETH execution layer paid by block builders.',
    },
    Revenue: {
