const token = {} as IJSON<string>

const HEADERS = {
  "Content-Type": "application/json",
  "X-API-KEY": getEnv('ALLIUM_API_KEY'),
};

async function startAlliumQuery(sqlQuery: string) {
  const query = await httpPost(`https://api.allium.so/api/v1/explorer/queries/phBjLzIZ8uUIDlp0dD3N/run-async`, {
    parameters: {
      fullQuery: sqlQuery
    }
  }, {
    headers: HEADERS
  })

  return query["run_id"]
}

async function retrieveAlliumResults(queryId: string) {
  const results = await httpGet(`https://api.allium.so/api/v1/explorer/query-runs/${queryId}/results?f=json`, {
    headers: HEADERS
  })
  return results.data
}

async function _queryAllium(sqlQuery: string) {
  let startTime = +Date.now() / 1e3

  const metadata: any = {
    application: "allium",
    query: sqlQuery,
    table: sqlQuery.split(/from/i)[1].split(/\s/)[1],
  }
  const API_KEY = HEADERS["X-API-KEY"]
  if (!API_KEY) {
    throw new Error("Allium API Key is required[Ignore this error for github bot]")
  }

  const _response = retry(
    async (bail) => {
      if (!token[sqlQuery]) {
        try {
          token[sqlQuery] = await startAlliumQuery(sqlQuery);
        } catch (e) {
          console.log("query run-async", e);
          throw e
        }
      }

      if (!token[sqlQuery]) {
        throw new Error("Couldn't get a token from allium")
      }

      const statusReq = await httpGet(`https://api.allium.so/api/v1/explorer/query-runs/${token[sqlQuery]}/status`, {
        headers: HEADERS
      })

      const status = statusReq
      if (status === "success") {
        return retrieveAlliumResults(token[sqlQuery])
      } else if (status === "failed") {
        console.log(`Query ${sqlQuery} failed`, statusReq.data)
        bail(new Error(`Query ${sqlQuery} failed, error ${JSON.stringify(statusReq.data)}`))
        return;
      }
      throw new Error("Still running")
    },
    {
      retries: 15,
      maxTimeout: 1000 * 60 * 2, // 2 minutes
      minTimeout: 1000 * 10, // 10 seconds
      randomize: true,
    }
  );

  let response;
  let success = false
  try {
    response = await _response
    success = true
    metadata.rows = response?.length
    let endTime = +Date.now() / 1e3
    await elastic.addRuntimeLog({ runtime: endTime - startTime, success, metadata, })
  } catch (e) {
    let endTime = +Date.now() / 1e3
    await elastic.addRuntimeLog({ runtime: endTime - startTime, success, metadata, })
    await elastic.addErrorLog({ error: (e?.toString()) as any, metadata, })
    throw e
  }
  return response
}


export const queryAllium = rateLimited(_queryAllium);

import * as sdk from '@defillama/sdk'
import axios from 'axios'

const Bucket = "dimensions-adapter-cache";

function getKey(project: string, chain: string) {
  return `cache/${project}/${chain}.json`
}

function getFileKey(project: string, chain: string) {
  return `${Bucket}/${getKey(project, chain)}`
}


export async function getCache(project: string, chain: string, { } = {}) {
  const fileKey = getFileKey(project, chain)

  try {
    const json = await sdk.cache.readCache(fileKey)
    if (!json || Object.keys(json).length === 0) throw new Error('Invalid data')
    return json
  } catch (e) {
    sdk.log('failed to fetch data from s3 bucket:', fileKey)
    // sdk.log(e)
    return {}
  }
}

export async function setCache(project: string, chain: string, cache: any) {
  const Key = getFileKey(project, chain)

  try {
    await sdk.cache.writeCache(Key, cache)
  } catch (e) {
    sdk.log('failed to write data to s3 bucket: ', Key)
    sdk.log(e)
  }
}

const configCache: any = {}

async function _setCache(project: string, chain: string, json: any) {
  if (!json || json?.error?.message) return;
  const strData = typeof json === 'string' ? json : JSON.stringify(json)
  let isValidData = strData.length > 42
  if (isValidData) // sometimes we get bad data/empty object, we dont overwrite cache with it
    await setCache(project, chain, json)
}

export async function getConfig(project: string, endpoint?: string, { fetcher }: {
  fetcher?: () => Promise<any>
} = {}) {
  if (!project || (!endpoint && !fetcher)) throw new Error('Missing parameters')
  const key = 'config-cache'
  const cacheKey = getKey(key, project)
  if (!configCache[cacheKey]) configCache[cacheKey] = _getConfig()
  return configCache[cacheKey]

  async function _getConfig() {
    try {
      let json
      if (endpoint) {
        json = (await axios.get(endpoint)).data
      } else {
        json = await fetcher!()
      }
      if (!json) throw new Error('Invalid data')
      await _setCache(key, project, json)
      return json
    } catch (e) {
      // sdk.log(e)
      sdk.log(project, 'tryng to fetch from cache, failed to fetch data from endpoint:', endpoint)
      return getCache(key, project)
    }
  }
}

export async function configPost(project: string, endpoint: string, data: any) {
  if (!project || !endpoint) throw new Error('Missing parameters')
  const key = 'config-cache'
  const cacheKey = getKey(key, project)
  if (!configCache[cacheKey]) configCache[cacheKey] = _configPost()
  return configCache[cacheKey]

  async function _configPost() {
    try {
      const { data: json } = await axios.post(endpoint, data)
      await _setCache(key, project, json)
      return json
    } catch (e) {
      // sdk.log(e)
      sdk.log(project, 'tryng to fetch from cache, failed to fetch data from endpoint:', endpoint)
      return getCache(key, project)
    }
  }
}

